import{_ as a,c as s,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Opciones de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy-choices.md","filePath":"es/guide/privacy-choices.md","lastUpdated":1793163976000}'),n={name:"es/guide/privacy-choices.md"};function t(r,e,c,d,l,p){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="opciones-de-privacidad" tabindex="-1">Opciones de privacidad <a class="header-anchor" href="#opciones-de-privacidad" aria-label="Permalink to &quot;Opciones de privacidad&quot;">​</a></h1><p>NueZip es una aplicación totalmente sin conexión. Como todos tus datos permanecen en tu dispositivo, no recopilamos, vendemos ni compartimos ninguna información personal.</p><h2 id="datos-que-conservamos-localmente" tabindex="-1">Datos que conservamos localmente <a class="header-anchor" href="#datos-que-conservamos-localmente" aria-label="Permalink to &quot;Datos que conservamos localmente&quot;">​</a></h2><p>NueZip almacena todos los datos localmente en tu Mac:</p><ul><li>Preferencias y configuración de la app</li><li>Lista de archivos recientes</li><li>Registros de depuración (si están habilitados)</li><li>Contraseñas almacenadas en la cadena de claves (si eliges guardarlas)</li></ul><p>Ninguno de estos datos se sube a ningún servidor.</p><h2 id="tus-derechos" tabindex="-1">Tus derechos <a class="header-anchor" href="#tus-derechos" aria-label="Permalink to &quot;Tus derechos&quot;">​</a></h2><p>Dado que NueZip no recopila ni almacena datos personales en nuestros servidores, no existe ningún dato personal al que podamos acceder, eliminar o transferir. Todos tus datos pueden gestionarse directamente dentro de la app o eliminando la carpeta de contenedor de la app:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><h2 id="no-venta" tabindex="-1">No venta <a class="header-anchor" href="#no-venta" aria-label="Permalink to &quot;No venta&quot;">​</a></h2><p>NueZip no vende ninguna información personal. No usamos analíticas de terceros, publicidad ni servicios de rastreo de ningún tipo.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>Si tienes preguntas sobre las opciones de privacidad, abre un issue en: <code>https://github.com/nuezip/nuezip/issues</code></p>',13)])])}const m=a(n,[["render",t]]);export{h as __pageData,m as default};
